import json,os,stat,subprocess
from pathlib import Path
base=Path("/srv/projects")
original=[base/"Engenheira-reversa",base/"REA-Trial"]
staged=[base/".pending-removal-rea-final-20261104",base/".pending-removal-rea-trial-20261104"]
ferrari=base/"skill-universal"
services=["ssh","nginx","lowcost-europa","pink-vpn","pm2-iptvpn-bot","pm2-telegram-robot-leads"]
result={"status":"BLOCKED","changed":False,"mode":"restore_previous_legacy_roots","source":[str(x) for x in staged],"destination":[str(x) for x in original]}
moved=[]
def cmd(name):
 p=subprocess.run(["/usr/bin/systemctl","is-active",name],capture_output=True,text=True,timeout=7)
 return p.stdout.strip() if p.returncode==0 else "NOT_ACTIVE"
def emit(**kw):
 result.update(kw)
 print(json.dumps(result,ensure_ascii=True,sort_keys=True))
try:
 if not base.is_dir() or base.is_symlink():raise RuntimeError("project_parent_not_physical")
 if any(p.exists() or p.is_symlink() for p in original):raise RuntimeError("original_target_already_occupied")
 if any(not p.is_dir() or p.is_symlink() or p.parent!=base or p.stat().st_dev!=base.stat().st_dev for p in staged):raise RuntimeError("staged_source_not_physical")
 if not all((staged[0]/name).is_dir() for name in ("original","runtime","evidence")):raise RuntimeError("rea_final_directory_shape_invalid")
 if not all((staged[1]/name).is_dir() for name in ("private","repository")):raise RuntimeError("rea_trial_directory_shape_invalid")
 if ferrari.is_symlink() or not (ferrari/".runtime/npm/rea/node_modules/rea-agents/package.json").is_file():raise RuntimeError("ferrari_private_rea_missing")
 before={s:cmd(s) for s in services}
 if any(s!="active" for s in before.values()):raise RuntimeError("service_not_active_before")
 for src,dst in zip(staged,original):
  src.rename(dst)
  moved.append((src,dst))
 after={s:cmd(s) for s in services}
 if after!=before:raise RuntimeError("service_changed_during_restore")
 if any(src.exists() or src.is_symlink() or not dst.is_dir() or dst.is_symlink() for src,dst in moved):raise RuntimeError("post_restore_paths_invalid")
 emit(status="RESTORED",changed=True,services=after,original_roots_present=True,staged_roots_absent=True,ferrari_private_rea_intact=True)
except Exception as e:
 rollback=[]
 for src,dst in reversed(moved):
  try:
   if dst.is_dir() and not src.exists() and not src.is_symlink():
    dst.rename(src)
    rollback.append(str(src))
  except Exception as ex:rollback.append("FAILED:"+type(ex).__name__)
 emit(status="BLOCKED" if not moved else "ROLLED_BACK" if len(rollback)==len(moved) else "RECOVERY_REQUIRED",changed=False,reason=type(e).__name__+":"+str(e)[:150],rollback=rollback)
